   ],
   "http_method": "POST",
   "path": "/payment-orders/payments",
   "legacy_program": "dbo.sp_pago_orden",
   "unit_of_work": {
    "begins_at": 108,
    "commits_at": 161,
    "savepoints": [],
    "rollbacks": [
     {
      "legacy_line": 119,
      "outcome": "DEBIT_FAILED"
     },
     {
      "legacy_line": 136,
      "outcome": "COMMISSION_FAILED"
     },
     {
      "legacy_line": 155,
      "outcome": "ORDER_UPDATE_FAILED"
     }
    ]
   },
   "legacy_message": "@o_mensaje"
  }
 ],
 "decisions": [
  {
   "title": "Transaction owned by the REST adapter",
   "context": "The legacy opens the transaction at line 108 and rejects with a non-zero return status (the error code) on every failure path, undoing everything with rollback tran at lines 119, 136 and 155.",
   "decision": "The use case does not manage the transaction. The REST adapter opens it and any business error rejects the request and undoes all the work, so no UnitOfWork port is declared. The validations before line 108 are read-only, so extending the transaction to the whole use case does not change the result.",
   "consequences": "A failed commission debit or a failed order update undoes the debit(s) already made, as in the legacy. The outcome of each rollback point is the business error listed in unit_of_work."
  },
  {
   "title": "Failure exits are business errors, not output data",
   "context": "The legacy returns @w_error as its non-zero return status together with the message in @o_mensaje, after calling cobis..sp_cerror.",
   "decision": "Each exit with codes 50001 to 50007 is a business error with a stable code; the legacy code and message are kept for replaying the golden master. The call to cobis..sp_cerror is infrastructure and is replaced by exception handling and logging.",
   "consequences": "The successful path returns movementSequence and the message 'PAGO REALIZADO'."
  },
  {
   "title": "Called program sp_debito stays behind a port (migration)",
   "context": "The data moves to the target database, but the account debit is a program of another system.",
   "decision": "DebitGateway wraps db_cuentas..sp_debito. The first debit reads the movement sequence and the return status. The commission debit, which has no output parameter, only reads the return status. A non-zero status maps to DEBIT_FAILED or COMMISSION_FAILED. The legacy check of @@error is covered by exceptions of the adapter.",
   "consequences": "The target can replace the gateway without touching the rules."
  },
  {
   "title": "Data migrated with target names",
   "context": "data_strategy is migration: the four legacy tables move to the Oracle target database.",
   "decision": "Tables and columns are renamed to English snake_case (pg_orden -> payment_order, ad_tarifa_empresa -> company_tariff, ad_servicio -> service_catalog, ct_cuenta -> account). Money columns keep decimal(19,4). DebitResult is a transport entity for the output of sp_debito and has no table.",
   "consequences": "The legacy column of every field is kept in the traceability."
  },
  {
   "title": "Preserved behaviour on missing data",
   "context": "In T-SQL a missing row leaves the variables null, and comparisons with null are not true.",
   "decision": "If no tariff is found (neither company nor service), the tariff is 0. If the company tariff row has a null separate-charge flag, the commission is added to the total (anything other than 'S'). If the account does not exist, the balance is null, the funds check does not reject and the debit program decides, exactly as in the legacy.",
   "consequences": "No new error is introduced for these cases."
  },
  {
   "title": "Commission rounding and defaults",
   "context": "round(@w_tarifa / 2, 2) in Sybase rounds half away from zero. @i_canal defaults to 'WEB' when not sent.",
   "decision": "The commission for the WEB channel uses BigDecimal division with HALF_UP rounding to 2 decimals and keeps scale 4. A missing channel is treated as 'WEB'. Service 'NOMINA' always gives commission 0. The overdraft margin of 100.00 applies to every account type except VIR.",
   "consequences": "Results are equal to the legacy for amounts with up to 4 decimals."
  }
 ],
 "masks": [],
 "infrastructure": [
  "cobis..sp_cerror"
 ],
 "data_strategy": "migration"
}

